<?php
namespace App\Console\Commands;
use App\Services\Shipping\ProviderStrategyResolver;use Illuminate\Console\Command;use Illuminate\Support\Facades\Storage;
final class B2cQuoteFlowMapCommand extends Command {protected $signature='zigo:b2c-quote-flow-map {--cp-origin=64000} {--cp-destination=64000} {--package-type=box} {--no-external-call} {--json}';protected $description='Mapea el flujo B2C real sin ejecutar llamadas externas.';public function handle(ProviderStrategyResolver $resolver):int{$decision=$resolver->resolve('quote','estafeta','stage');$steps=[['step'=>1,'name'=>'route','evidence'=>'routes/web.php -> B2C quote routes'],['step'=>2,'name'=>'controller','evidence'=>'CotizacionPublicaController::getAvailableOptions'],['step'=>3,'name'=>'service','evidence'=>'ZigoProviderRateService::getOptionsForCotizacion'],['step'=>4,'name'=>'provider_selection','value'=>config('services.shipping.provider')],['step'=>5,'name'=>'ltd','value'=>config('services.xperta.ltd','estafeta')],['step'=>6,'name'=>'credentials','value'=>'services.xperta configured flags only'],['step'=>7,'name'=>'http','value'=>$decision['http_provider']??'none'],['step'=>8,'name'=>'normalization','evidence'=>'XpertaQuoteService::quote'],['step'=>9,'name'=>'provider_price','value'=>'base_price / provider_base_price'],['step'=>10,'name'=>'contract_rate','evidence'=>'ZigoContractRateService'],['step'=>11,'name'=>'margin','evidence'=>'ZigoCommercialQuoteService'],['step'=>12,'name'=>'insurance','evidence'=>'CotizacionPublicaController::applyPricingToCotizacion'],['step'=>13,'name'=>'tax','value'=>'pricing services'],['step'=>14,'name'=>'persistence','value'=>'B2cCotizacion'],['step'=>15,'name'=>'frontend','value'=>'B2C options view']];$report=['generated_at'=>now()->toIso8601String(),'input'=>['cp_origin'=>$this->mask((string)$this->option('cp-origin')),'cp_destination'=>$this->mask((string)$this->option('cp-destination')),'package_type'=>$this->option('package-type')],'external_call_executed'=>false,'strategy'=>$decision,'steps'=>$steps];$path='private/shipping-contract-audits/b2c-flow-'.now()->format('Ymd-His').'.json';Storage::disk('local')->put($path,json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));$this->line($this->option('json')?json_encode($report,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES):'Reporte: storage/app/'.$path);return self::SUCCESS;}private function mask(string $cp):string{return substr($cp,0,2).'***';}}
